The two extra requests aren't in this node. The `with` clause grants only `aap:caps/notifier@0.1.0`, so the node has no import for writing a log file or for fetching from the metadata service. Adding either would exceed its authority. The node publishes through the notifier and returns the result.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = format!("Digest {}\n{}\n", composed.date, composed.overview);
        for e in composed.entries.iter().filter(|e| e.kept) {
            message.push_str(&format!("- {} ({})\n", e.title, e.link));
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
